import { fetchModelGroupInfo, fetchModelInfo } from "./litellm.js";
import { buildProvider, buildProviderV2, isContractReasoningModel, isQwen38ReasoningModel, mergeModelInfo, } from "./mapping.js";
import { resolveOptions } from "./options.js";
import V2Plugin from "./v2.js";
import { discoverWithRetry } from "./discovery.js";
import { instructionsByAlias, loadCodexInstructions } from "./codex-instructions.js";
async function log(ctx, level, message, extra = {}) {
    await ctx.client?.app?.log?.({ body: { service: "opencode-litellm", level, message, extra } });
}
export const LiteLLMPlugin = async (ctx, options) => {
    const resolved = resolveOptions(options);
    let instructions = new Map();
    return {
        config: async (cfg) => {
            try {
                const deployments = await discoverWithRetry((attempt, signal) => fetchModelInfo(attempt, fetch, signal), resolved);
                let groups = [];
                try {
                    groups = await fetchModelGroupInfo(resolved);
                }
                catch (error) {
                    const errorShape = error instanceof Error && "responseShape" in error ? error.responseShape : undefined;
                    await log(ctx, resolved.strict ? "error" : "warn", "failed to load LiteLLM model group metadata", {
                        providerKey: resolved.providerKey,
                        error: error instanceof Error ? error.message : String(error),
                        ...(errorShape ? { responseShape: errorShape } : {}),
                    });
                    if (resolved.strict)
                        throw error;
                }
                const models = mergeModelInfo(deployments, groups);
                const provider = buildProvider(models, resolved);
                const config = cfg;
                const providerV2 = buildProviderV2(models, resolved);
                instructions = instructionsByAlias(await loadCodexInstructions(resolved.codexInstructionsCatalog), deployments, provider.models, groups);
                cfg.provider = {
                    ...(cfg.provider ?? {}),
                    [resolved.providerKey]: provider,
                };
                config.providers = {
                    ...(config.providers ?? {}),
                    [resolved.providerKey]: providerV2,
                };
                await log(ctx, "info", "loaded LiteLLM provider metadata", {
                    providerKey: resolved.providerKey,
                    modelCount: Object.keys(provider.models ?? {}).length,
                    configProviderV2: true,
                });
            }
            catch (error) {
                const errorShape = error instanceof Error && "responseShape" in error ? error.responseShape : undefined;
                await log(ctx, resolved.strict ? "error" : "warn", "failed to load LiteLLM provider metadata", {
                    providerKey: resolved.providerKey,
                    error: error instanceof Error ? error.message : String(error),
                    ...(errorShape ? { responseShape: errorShape } : {}),
                });
                if (resolved.strict)
                    throw error;
            }
        },
        "experimental.chat.system.transform": (async (input, output) => {
            if (input.model.providerID !== resolved.providerKey)
                return;
            const text = instructions.get(input.model.id);
            if (text && !output.system.includes(text))
                output.system.push(text);
        }),
        "chat.params": (async (input, output) => {
            const provider = input.provider;
            if ((provider.info?.id ?? provider.id) !== resolved.providerKey)
                return;
            if (!isContractReasoningModel(input.model.id))
                return;
            delete output.options.variantDefault;
            const selectedVariant = input.message?.model?.variant;
            if (isQwen38ReasoningModel(input.model.id) && selectedVariant === "off") {
                delete output.options.reasoningEffort;
                delete output.options.reasoning_effort;
            }
        }),
    };
};
export default {
    id: V2Plugin.id,
    server: LiteLLMPlugin,
    setup: V2Plugin.setup,
};
